<section class="panel"><div class="panel-heading"><div><span class="eyebrow">MANAGE CONTENT</span><h2><?= e($title) ?> <span class="count"><?= $total ?></span></h2></div><a class="btn btn-primary" href="<?= e(url('admin/'.$type.'/create?'.http_build_query(['return_to'=>$returnTo]))) ?>">+ Add record</a></div>
<form class="admin-filters content-filters" method="get" action="<?= url('admin/'.$type) ?>"><div><label for="q">Search</label><input type="search" name="q" id="q" value="<?= e($q) ?>" maxlength="190" placeholder="Search <?= e(strtolower($title)) ?>"></div>
<?php if($type!=='categories'): ?><div><label for="status">Publication</label><select id="status" name="status"><option value="">All records</option><?php foreach(['published'=>'Published','draft'=>'Draft'] as $value=>$label): ?><option value="<?= $value ?>" <?= $filters['status']===$value?'selected':'' ?>><?= $label ?></option><?php endforeach; ?></select></div><?php endif; ?>
<?php if($type==='products'): ?><div><label for="category">Category</label><select id="category" name="category"><option value="">All categories</option><?php foreach($categories as $c): ?><option value="<?= $c['id'] ?>" <?= $category==$c['id']?'selected':'' ?>><?= e($c['name']) ?></option><?php endforeach; ?></select></div><?php endif; ?>
<?php if(in_array($type,['articles','documents'])): $choices=$type==='articles'?['knowledge'=>'Knowledge article','news'=>'News / announcement']:['catalogue'=>'Product catalogue','company_profile'=>'Company profile','certificate'=>'Certificate','technical'=>'Technical document']; ?><div><label for="kind">Content type</label><select id="kind" name="kind"><option value="">All types</option><?php foreach($choices as $value=>$label): ?><option value="<?= $value ?>" <?= $filters['kind']===$value?'selected':'' ?>><?= $label ?></option><?php endforeach; ?></select></div><?php endif; ?>
<?php if(in_array($type,['dealers','documents','manufacturing_updates'])): ?><div><label for="verified">Company verification</label><select id="verified" name="verified"><option value="">All records</option><option value="yes" <?= $filters['verified']==='yes'?'selected':'' ?>>Verified</option><option value="no" <?= $filters['verified']==='no'?'selected':'' ?>>Needs verification</option></select></div><?php endif; ?>
<div><label for="sort">Sort by</label><select id="sort" name="sort"><?php foreach($sorts as $sort): ?><option value="<?= $sort ?>" <?= $filters['sort']===$sort?'selected':'' ?>><?= ['newest'=>'Newest first','oldest'=>'Oldest first','name'=>'Name / title','display'=>'Display order','updated'=>'Recently updated'][$sort] ?></option><?php endforeach; ?></select></div><div class="filter-actions"><button class="btn">Filter</button><a class="btn" href="<?= url('admin/'.$type) ?>">Reset</a></div></form>
<div class="table-wrap"><table><thead><tr><th><?= in_array($type,['products','categories'])?'Name':'Title' ?></th><th><?= $type==='products'?'Category':($type==='contacts'?'Contact information':'Details') ?></th><th><?= $type==='products'?'Documents':'Order' ?></th><th>Status</th><th class="actions-col">Actions</th></tr></thead><tbody>
<?php foreach($rows as $row): $editPath='admin/'.$type.'/'.$row['id'].'/edit?'.http_build_query(['return_to'=>$returnTo]);$publicPath=admin_public_path($type,$row); ?><tr>
<td><div class="table-identity"><?php if(!empty($row['image'])): ?><img src="<?= e(media($row['image'])) ?>" alt=""><?php endif; ?><div><strong><?= e($row['name']??$row['title']) ?></strong><small>#<?= $row['id'] ?><?php if(in_array($type,['products','articles'])): ?> · <a href="<?= url('admin/preview/'.$type.'/'.$row['id']) ?>" target="_blank" rel="noopener">Preview ↗</a><?php elseif($publicPath!==null): ?> · <a href="<?= e(url($publicPath)) ?>" target="_blank" rel="noopener">View on website ↗</a><?php endif; ?></small></div></div></td>
<td><?php if($type==='products'): ?><?= e(array_column($categories,'name','id')[$row['category_id']]??'') ?><small><?= e($row['product_code']) ?></small><?php elseif($type==='contacts'): ?><?= e($row['email']) ?><small><?= e($row['phone']) ?></small><?php elseif($type==='dealers'): ?><?= e($row['region'].' / '.$row['city']) ?><small><?= e($row['township']) ?> · <?= $row['verified']?'Verified':'Needs verification' ?></small><?php elseif($type==='articles'): ?><?= e($row['kind']==='knowledge'?'Knowledge article':'News / announcement') ?><small><?= e($row['topic']) ?></small><?php elseif($type==='documents'): ?><?= e(ucwords(str_replace('_',' ',$row['document_type']))) ?><small><?= $row['verified']?'Verified':'Needs verification' ?><?php if($row['file']): ?> · <a href="<?= e(media($row['file'])) ?>" target="_blank" rel="noopener">PDF ↗</a><?php endif; ?></small><?php elseif($type==='manufacturing_updates'): ?><?= e(ucfirst($row['stage'])) ?><small><?= $row['verified']?'Verified':'Needs verification' ?></small><?php else: ?><?= e(mb_substr(strip_tags($row['description']??''),0,100)) ?><?php endif; ?></td>
<td><?php if($type==='products'): ?><small><?= $row['data_sheet']?'✓ TDS':'— TDS' ?></small><small><?= $row['safety_sheet']?'✓ SDS':'— SDS' ?></small><?php else: ?><?= $row['sort_order'] ?><?php endif; ?></td>
<td><?php if($type==='categories'): ?><span class="badge">Category</span><?php else: ?><span class="badge <?= $row['published']?'published':'draft' ?>"><?= $row['published']?'● Published':'○ Draft' ?></span><?php endif; ?></td>
<td class="actions-col"><div class="row-actions"><a class="btn btn-sm" href="<?= e(url($editPath)) ?>" aria-label="Edit <?= e($row['name']??$row['title']) ?>">Edit</a><form method="post" class="delete-form" data-name="<?= e($row['name']??$row['title']) ?>" action="<?= url('admin/'.$type.'/'.$row['id'].'/delete') ?>"><?= csrf_field() ?><input type="hidden" name="return_to" value="<?= e($returnTo) ?>"><button class="btn btn-sm danger-text" aria-label="Delete <?= e($row['name']??$row['title']) ?>">Delete</button></form></div></td></tr>
<?php endforeach; ?><?php if(!$rows): ?><tr><td colspan="5" class="empty">No records found. <a href="<?= url('admin/'.$type.'/create') ?>">Add a record</a> or adjust your filters.</td></tr><?php endif; ?></tbody></table></div>
